const materials=new Map(),geometries=new Map();
export function material(color,metal=false){const key=color+':'+metal;if(!materials.has(key))materials.set(key,new T.MeshStandardMaterial({color,roughness:metal?.34:.74,metalness:metal?.55:0}));return materials.get(key);}
