export function box(g,x,y,z,w,h,d,color,r=.08){const geo=geometry(`b:${w}:${h}:${d}:${r}`,()=>r?new RoundedBoxGeometry(w,h,d,1,Math.min(r,w/2,h/2,d/2)):new T.BoxGeometry(w,h,d));const m=new T.Mesh(geo,material(color));m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;g.add(m);return m;}
export function sphere(g,x,y,z,r,color,sx=1,sy=1,sz=1){const m=new T.Mesh(geometry('sphere',()=>new T.SphereGeometry(1,16,12)),material(color));m.position.set(x,y,z);m.scale.set(r*sx,r*sy,r*sz);m.castShadow=true;g.add(m);return m;}
