for(const id of extraKinds)makers[id]=g=>{const parts=Object.fromEntries(extraPartIds[id].map(key=>{const part=new T.Group();g.add(part);return [key,part];}));buildExtra(id,parts,{box,sphere,cylinder,rod,ring,palette});if(id==='ac_split')g.remove(parts.outdoor);};
export const modelIds=Object.freeze(Object.keys(makers));
export function createItem(id,{normalise=true,showPower=true}={}){const g=new T.Group();g.name=id;(makers[id]||makers.mystery_toy)(g);if(!showPower)g.traverse(n=>{if(n.userData.power)n.visible=false;});g.updateMatrixWorld(true);const bounds=new T.Box3().setFromObject(g),size=bounds.getSize(new T.Vector3()),center=bounds.getCenter(new T.Vector3());if(normalise){g.position.set(-center.x,-bounds.min.y,-center.z);const wrap=new T.Group();wrap.add(g);wrap.scale.setScalar(1.7/Math.max(size.x,size.y,size.z));wrap.userData.object=g;wrap.userData.id=id;return wrap;}g.userData.id=id;return g;}
export function reactToClue(model,strength=1){model.userData.pulse=strength;model.traverse(n=>{if(n.userData.power){n.visible=true;n.userData.revealed=true;}});}
export function animateItem(model,time,dt,reduced=false){const g=model.userData.object||model;if(!reduced&&g.userData.rotor)g.userData.rotor.rotation.z=time*.65;const pulse=model.userData.pulse||0;if(pulse>0){model.userData.pulse=Math.max(0,pulse-dt*.32);g.traverse(n=>{if(n.userData.power){const s=1+Math.sin(time*6)*.06*pulse;n.scale.setScalar(reduced?1:s);}});}}
export const avatarDefaults={skin:1,hair:0,style:0,face:0,outfit:0,glasses:false};
export const avatarOptions={skin:['#e9b793','#bf805c','#815139','#513726'],hair:['#30252b','#654032','#c28b48','#e8d1a7'],outfit:['#1aa68a','#6979d7','#ef8391','#f4c24d'],style:['Short','Curls','Long','Cap'],face:['Smile','Big smile','Curious','Calm']};
export function cleanAvatar(v){const a={...avatarDefaults};for(const k of ['skin','hair','style','face','outfit'])if(Number.isInteger(v?.[k])&&v[k]>=0&&v[k]<4)a[k]=v[k];a.glasses=v?.glasses===true;return a;}
export function createAvatar(settings={}){const v=cleanAvatar(settings),g=new T.Group(),skin=avatarOptions.skin[v.skin],hair=avatarOptions.hair[v.hair],shirt=avatarOptions.outfit[v.outfit];const body=box(g,0,.65,0,.4,.47,.29,shirt,.10);sphere(g,0,1.11,0,.25,skin,1,1.08,.90);for(const x of [-.25,.25])sphere(g,x,1.1,0,.059,skin);sphere(g,0,1.31,-.035,.253,hair,1,.48,.94);if(v.style===1)for(let i=0;i<8;i++){const a=i*Math.PI/4;sphere(g,Math.cos(a)*.19,1.31+Math.sin(i)*.025,Math.sin(a)*.17,.105,hair);}if(v.style===2)box(g,0,1.07,-.16,.49,.52,.16,hair,.1);if(v.style===3){sphere(g,0,1.32,-.025,.263,shirt,1,.55,1);box(g,0,1.3,.23,.36,.045,.29,shirt,.035);}for(const x of [-.085,.085]){sphere(g,x,1.14,.213,.028,palette.dark,1,1.1,.4);if(v.glasses){ring(g,x,1.14,.23,.065,.011,palette.deep);}}if(v.glasses)rod(g,[-.02,1.14,.23],[.02,1.14,.23],.009,palette.deep);sphere(g,0,1.065,.241,.022,skin);if(v.face===1){sphere(g,0,1.005,.220,.058,palette.deep,1,.75,.25);sphere(g,0,.985,.236,.027,palette.pink,1,.4,.2);}else if(v.face===2){sphere(g,0,1.005,.221,.032,palette.deep,1,1,.3);rod(g,[.054,1.22,.214],[.118,1.24,.201],.01,hair);}else if(v.face===3){rod(g,[-.038,1.015,.217],[.038,1.015,.217],.009,palette.deep);}else{const smile=ring(g,0,1.005,.219,.05,.010,palette.deep,Math.PI);smile.rotation.z=Math.PI;}const limbs=[];for(const x of [-.13,.13]){const leg=new T.Group();leg.position.set(x,.44,0);box(leg,0,-.16,0,.14,.33,.16,palette.deep,.05);box(leg,0,-.35,.055,.18,.10,.30,palette.white,.035);g.add(leg);limbs.push(leg);}for(const x of [-.28,.28]){const arm=new T.Group();arm.position.set(x,.80,0);box(arm,0,-.13,0,.13,.30,.15,shirt,.05);sphere(arm,0,-.32,0,.082,skin);g.add(arm);limbs.push(arm);}g.userData.limbs=limbs;g.userData.body=body;return g;}
export function walkAvatar(g,time,moving,reduced=false){const n=reduced?0:moving?Math.sin(time*10)*.46:0;g.userData.limbs?.forEach((limb,i)=>limb.rotation.x=n*(i%2?1:-1));if(g.userData.body)g.userData.body.position.y=.65+(moving&&!reduced?Math.abs(Math.sin(time*10))*.02:0);}
